type ctxKey string

const logKey ctxKey = "logger"

// RequestLogger stamps a request_id onto a child logger in the context.
func RequestLogger(base *slog.Logger, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		l := base.With(
			slog.String("request_id", "abc-123"),
			slog.String("path", r.URL.Path),
		)
		ctx := context.WithValue(r.Context(), logKey, l)
		l.Info("request received")
		next.ServeHTTP(w, r.WithContext(ctx))
	})
}
// Every handler that reads the logger from ctx logs the same request_id.
